def suma_iterativa(n):
    ops = 0
    total = 0
    for i in range(1, n + 1):
        total += i
        ops += 1                    # una suma por vuelta
    return total, ops

def suma_formula(n):
    return n * (n + 1) // 2, 1      # un número fijo de operaciones, sin importar n

