def sumar(v):
    ops = 1                      # total = 0
    total = 0
    for i in range(len(v)):
        ops += 4                 # 1 de control del ciclo + 3 (acceso v[i], suma, asignación)
        total += v[i]
    ops += 1                     # return
    return total, ops

def hay_duplicados(v):
    comparaciones = 0
    n = len(v)
    for i in range(n):
        for j in range(i + 1, n):        # (n-1) + (n-2) + ... + 1 vueltas en total
            comparaciones += 1
            if v[i] == v[j]:
                return True, comparaciones
    return False, comparaciones

