def procesar(v):
    n = len(v)
    ops = [0, 0, 0]               # operaciones de los bloques 1, 2 y 3
    total = 0
    for x in v:                   # bloque 1: O(n)
        total += x
        ops[0] += 1
    for i in range(n):            # bloque 2: O(n^2)
        for j in range(n):
            if v[i] == v[j]:
                total += 1
            ops[1] += 1
    ops[2] += 1                   # bloque 3: return, O(1)
    return total, ops

