def f1(n):                      # doble ciclo independiente
    c = 0
    for i in range(n):
        for j in range(n):
            c += 1
    return c

def f2(n):                      # se divide a la mitad
    c, i = 0, n
    while i > 1:
        i = i // 2
        c += 1
    return c

def f3(n):                      # lineal por logarítmico
    c = 0
    for i in range(n):
        j = 1
        while j < n:
            j *= 2
            c += 1
    return c

def f4(n):                      # triple ciclo dependiente
    c = 0
    for i in range(n):
        for j in range(i):
            for k in range(j):
                c += 1
    return c

