import math

def logaritmico(n):
    c, i = 0, n
    while i > 1:
        i //= 2
        c += 1
    return c

def lineal(n):
    c = 0
    for i in range(n):
        c += 1
    return c

def nlogn(n):
    c = 0
    for i in range(n):
        j = 1
        while j < n:
            j *= 2
            c += 1
    return c

def cuadratico(n):
    c = 0
    for i in range(n):
        for j in range(n):
            c += 1
    return c

