def reinas_fb(n):
    total, validas = [0], [0]
    def rec(fila, cols):
        if fila == n:
            total[0] += 1
            ok = True
            for i in range(n):
                for j in range(i + 1, n):
                    if cols[i] == cols[j] or abs(cols[i] - cols[j]) == j - i:
                        ok = False
            if ok:
                validas[0] += 1
            return
        for c in range(n):
            rec(fila + 1, cols + [c])
    rec(0, [])
    return validas[0], total[0]

def reinas_bt(n):
    nodos, soluciones = [0], [0]
    def segura(cols, c):
        fila = len(cols)
        for i in range(fila):
            if cols[i] == c or abs(cols[i] - c) == fila - i:
                return False
        return True
    def rec(cols):
        nodos[0] += 1
        if len(cols) == n:
            soluciones[0] += 1
            return
        for c in range(n):
            if segura(cols, c):          # poda: solo se continúa con columnas seguras
                rec(cols + [c])
    rec([])
    return soluciones[0], nodos[0]

