def busqueda_binaria(v, x):
    lo, hi, pasos = 0, len(v) - 1, 0
    while lo <= hi:
        pasos += 1
        m = (lo + hi) // 2
        if v[m] == x:
            return m, pasos
        if v[m] < x:
            lo = m + 1                 # descartar la mitad izquierda
        else:
            hi = m - 1                 # descartar la mitad derecha
    return -1, pasos

