def construir(pre, ino):
    if not pre:
        return None
    raiz = NodoArbol(pre[0])                  # el primero del preorden es la raíz
    k = ino.index(pre[0])                     # posición de la raíz en el inorden
    raiz.izq = construir(pre[1:k + 1], ino[:k])
    raiz.der = construir(pre[k + 1:], ino[k + 1:])
    return raiz

