def evaluar_rpn(tokens):                # la misma evaluación con una pila
    pila = []
    for t in tokens:
        if t in OPS:
            b = pila.pop()
            a = pila.pop()
            pila.append(OPS[t](a, b))
        else:
            pila.append(t)
    return pila[0]

