class NodoArbol:
    def __init__(self, valor):
        self.valor = valor
        self.izq = None
        self.der = None

def insertar(nodo, v):
    if nodo is None:
        return NodoArbol(v)
    if v < nodo.valor:
        nodo.izq = insertar(nodo.izq, v)
    elif v > nodo.valor:
        nodo.der = insertar(nodo.der, v)
    return nodo

def buscar(nodo, v):
    visitados = 0
    while nodo is not None:
        visitados += 1
        if v == nodo.valor:
            return True, visitados
        nodo = nodo.izq if v < nodo.valor else nodo.der
    return False, visitados

def inorden(nodo, salida):
    if nodo is not None:
        inorden(nodo.izq, salida)
        salida.append(nodo.valor)
        inorden(nodo.der, salida)
    return salida

